/**
 * Версия приложения, которую подставляет сборка (`vite.config.ts`). Объявлена
 * отдельной константой, а не полем `import.meta.env`: объект окружения Vite
 * подставляет целиком, и подмена его поля до браузерных прогонов не доходит.
 *
 * Вне сборки константы нет вовсе — обращение к ней защищено проверкой
 * `typeof`, поэтому dev-сервер и тесты работают без неё.
 */
declare const __APP_VERSION__: string;
